// <auto-generated />
#nullable enable

namespace DialogsShowcase.Services;

/// <summary>
/// 跨平台現代化訊息對話視窗。
/// </summary>
public sealed class MessageBoxWindow : Window
{
    public MessageBoxWindow(string title, string message, MessageBoxButtons buttons = MessageBoxButtons.OkCancel)
    {
        Title = title;
        Width = 400;
        Height = 170;
        WindowStartupLocation = WindowStartupLocation.CenterOwner;
        CanResize = false;
        Background = Brush.Parse("#18181B");

        var grid = new Grid
        {
            Margin = new Thickness(20),
            RowDefinitions = new RowDefinitions("*, Auto")
        };

        var textBlock = new TextBlock
        {
            Text = message,
            Foreground = Brushes.White,
            FontSize = 13,
            TextWrapping = TextWrapping.Wrap,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetRow(textBlock, 0);

        var buttonPanel = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Right,
            Spacing = 10
        };
        Grid.SetRow(buttonPanel, 1);

        switch (buttons)
        {
            case MessageBoxButtons.Ok:
            {
                var okButton = new Button
                {
                    Content = "確定",
                    Padding = new Thickness(20, 6),
                    Background = Brush.Parse("#0284C7"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                okButton.Click += (s, e) => Close(true);
                buttonPanel.Children.Add(okButton);
                break;
            }
            case MessageBoxButtons.YesNo:
            {
                var yesButton = new Button
                {
                    Content = "是",
                    Padding = new Thickness(20, 6),
                    Background = Brush.Parse("#10B981"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                yesButton.Click += (s, e) => Close(true);

                var noButton = new Button
                {
                    Content = "否",
                    Padding = new Thickness(20, 6),
                    Background = Brush.Parse("#EF4444"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                noButton.Click += (s, e) => Close(false);

                buttonPanel.Children.Add(yesButton);
                buttonPanel.Children.Add(noButton);
                break;
            }
            case MessageBoxButtons.YesNoCancel:
            {
                var yesButton = new Button
                {
                    Content = "是",
                    Padding = new Thickness(16, 6),
                    Background = Brush.Parse("#10B981"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                yesButton.Click += (s, e) => Close(true);

                var noButton = new Button
                {
                    Content = "否",
                    Padding = new Thickness(16, 6),
                    Background = Brush.Parse("#EF4444"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                noButton.Click += (s, e) => Close(false);

                var cancelButton = new Button
                {
                    Content = "取消",
                    Padding = new Thickness(16, 6),
                    Background = Brush.Parse("#3F3F46"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                cancelButton.Click += (s, e) => Close(null);

                buttonPanel.Children.Add(yesButton);
                buttonPanel.Children.Add(noButton);
                buttonPanel.Children.Add(cancelButton);
                break;
            }
            case MessageBoxButtons.OkCancel:
            default:
            {
                var okButton = new Button
                {
                    Content = "確定",
                    Padding = new Thickness(16, 6),
                    Background = Brush.Parse("#0284C7"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                okButton.Click += (s, e) => Close(true);

                var cancelButton = new Button
                {
                    Content = "取消",
                    Padding = new Thickness(16, 6),
                    Background = Brush.Parse("#3F3F46"),
                    Foreground = Brushes.White,
                    CornerRadius = new CornerRadius(6)
                };
                cancelButton.Click += (s, e) => Close(false);

                buttonPanel.Children.Add(okButton);
                buttonPanel.Children.Add(cancelButton);
                break;
            }
        }

        grid.Children.Add(textBlock);
        grid.Children.Add(buttonPanel);

        Content = grid;
    }
}
